402 | /** Formats minutes-from-midnight into a 12-hour "hh:mm AM/PM" label. */
403 | const formatMinutesAsTime = (mins: number) => {
404 |   const total = ((mins % (24 * 60)) + 24 * 60) % (24 * 60);
405 |   const h = Math.floor(total / 60);
406 |   const m = total % 60;
407 |   const suffix = h >= 12 ? "PM" : "AM";
408 |   const h12 = h % 12 === 0 ? 12 : h % 12;
409 |   return `${String(h12).padStart(2, "0")}:${String(m).padStart(2, "0")} ${suffix}`;
