412 | /** Builds the day's time slots from a start time, interval and slot count. */
413 | const buildTimeSlots = (startTime: string, intervalMinutes: number, count: number) => {
414 |   const [h, m] = startTime.split(":").map(Number);
415 |   const base = (h ?? 8) * 60 + (m ?? 0);
416 |   return Array.from({ length: Math.max(1, count) }, (_, i) => {
417 |     const total = (base + i * Math.max(5, intervalMinutes)) % (24 * 60);
418 |     const hour24 = Math.floor(total / 60);
419 |     const minute = total % 60;
420 |     const suffix = hour24 >= 12 ? "PM" : "AM";
421 |     const hour12 = hour24 % 12 === 0 ? 12 : hour24 % 12;
422 |     return `${String(hour12).padStart(2, "0")}:${String(minute).padStart(2, "0")} ${suffix}`;
423 |   });
424 | };
