426 | /** Builds the full daily schedule (start/end minutes + labels), flagging any slot that overlaps the break window. */
427 | const buildSlotSchedule = (
428 |   startTime: string,
429 |   intervalMinutes: number,
430 |   count: number,
431 |   breakEnabled: boolean,
432 |   breakStart: string,
433 |   breakEnd: string,
434 | ) => {
435 |   const [h, m] = startTime.split(":").map(Number);
436 |   const base = (h ?? 8) * 60 + (m ?? 0);
437 |   const step = Math.max(5, intervalMinutes);
438 |   const breakStartMin = parseTimeToMinutes(breakStart);
439 |   const breakEndMin = parseTimeToMinutes(breakEnd);
440 |   return Array.from({ length: Math.max(1, count) }, (_, i) => {
441 |     const startMin = base + i * step;
442 |     const endMin = startMin + step;
443 |     const isBreak = breakEnabled && startMin < breakEndMin && endMin > breakStartMin;
444 |     return {
445 |       startMin,
446 |       endMin,
447 |       label: formatMinutesAsTime(startMin),
448 |       endLabel: formatMinutesAsTime(endMin),
449 |       isBreak,
450 |     };
451 |   });
452 | };
