const convertResumeToPdf = async (input: { file?: File; url?: string }, name: string) => {
  try {
    let buffer: ArrayBuffer;
    if (input.file) buffer = await input.file.arrayBuffer();
    else {
      const resp = await fetch(input.url!);
      if (!resp.ok) throw new Error("fetch failed");
      buffer = await resp.arrayBuffer();
    }
    let html = "";
    try {
      const mammoth = await import("mammoth");
      const result = await mammoth.convertToHtml({ arrayBuffer: buffer });
      html = `<div class="doc">${result.value}</div>`;
    } catch {
      // Not a docx — try plain text (legacy .doc / RTF-ish)
      const data = new TextDecoder("utf-8").decode(buffer);
      const stripped = data.replace(/[\x00-\x08\x0b\x0c\x0e-\x1f]/g, "");
      if (/<html|<body|<\w+[^>]*>/i.test(stripped)) {
        html = stripped;
      } else {
        html = `<pre>${stripped.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")}</pre>`;
      }
    }
    openPrintableWindow(html, name);
  } catch (e) {
    toast.error("Could not convert this document to PDF preview.");
  }
};
