/** Converts an uploaded resume (docx/doc) into a printable PDF using mammoth when possible. */
const convertResumeToPdf = useCallback(
  async (input: { file?: File | null; url?: string | null }, name: string) => {
    try {
      let buffer: ArrayBuffer;
      if (input.file) {
        buffer = await input.file.arrayBuffer();
      } else if (input.url) {
        const resp = await fetch(input.url);
        if (!resp.ok) throw new Error("fetch failed");
        buffer = await resp.arrayBuffer();
      } else {
        throw new Error("no source");
      }
      let html: string;
      try {
        const mammoth = await import("mammoth");
        const result = await mammoth.convertToHtml({ arrayBuffer: buffer });
        html = result.value || "<p><em>No readable content found.</em></p>";
      } catch {
        const decoded = new TextDecoder("utf-8").decode(buffer).replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g, "");
        if (/<html|<body|<head|<(\w+)[^>]*>/i.test(decoded)) {
          html = decoded;
        } else {
          html = `<pre style="white-space:pre-wrap;font-family:Consolas,monospace;font-size:10pt;">${decoded.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")}</pre>`;
        }
      }
      openPrintableHtml(html, name || "Resume Preview");
    } catch (e) {
      console.warn("Resume PDF conversion failed:", e);
      toast.error("Could not convert this document to a PDF preview. Try opening it directly in Word.");
    }
  },
  [openPrintableHtml],
);
```

