  /** Opens a print window with the resume content so the user can "Save as PDF". */
  const openPrintableResume = useCallback((html: string, title: string) => {
    const w = window.open("", "_blank");
    if (!w) {
      toast.error("Please allow pop-ups so the resume can be converted to a PDF preview.");
      return;
    }
    const safeTitle = title.replace(/</g, "&lt;").replace(/>/g, "&gt;");
    w.document.write(`<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>${safeTitle}</title>
<style>
  @page { size: A4; margin: 18mm 14mm; }
  body { font-family: Calibri, Arial, sans-serif; color: #111827; line-height: 1.55; margin: 0; }
  .resume-doc { max-width: 100%; word-wrap: break-word; }
  .resume-doc p, .resume-doc li, .resume-doc td, .resume-doc th { font-size: 11pt; }
  .resume-doc h1 { font-size: 20pt; } .resume-doc h2 { font-size: 16pt; }
  .resume-doc h3 { font-size: 13pt; } .resume-doc h4 { font-size: 11pt; }
  .resume-doc table { border-collapse: collapse; width: 100%; }
  .resume-doc img { max-width: 100%; height: auto; }
</style>
</head>
<body>
<div class="resume-doc">${html}</div>
<script>
  window.onload = function () {
    window.focus();
    setTimeout(function () { window.print(); }, 350);
  };
<\/script>
</body>
</html>`);
    w.document.close();
  }, []);

  /** Converts an uploaded/server resume (.doc/.docx that cannot be previewed) into a
   *  printable PDF preview — Word payloads are converted to HTML via mammoth, then
   *  the print dialog ("Save as PDF") renders a clean A4 document. */
  const convertResumeToPdf = useCallback(
    async (input: { file?: File | null; url?: string | null }, title: string) => {
      try {
        let buffer: ArrayBuffer;
        if (input.file) {
          buffer = await input.file.arrayBuffer();
        } else if (input.url) {
          const resp = await fetch(input.url);
          if (!resp.ok) throw new Error("fetch failed");
          buffer = await resp.arrayBuffer();
        } else {
          throw new Error("no resume source");
        }
        let html: string;
        try {
          const mammoth = await import("mammoth");
          const result = await mammoth.convertToHtml({ arrayBuffer: buffer });
          html = result.value || "<p><em>No readable content was found.</em></p>";
        } catch {
          const decoded = new TextDecoder("utf-8")
            .decode(buffer)
            .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f]/g, "");
          if (/<(html|body|head|div|p|table|h[1-6])\b/i.test(decoded)) {
            html = decoded;
          } else {
            html = `<pre style="white-space:pre-wrap;font-family:Consolas,monospace;font-size:10pt;">${decoded
              .replace(/&/g, "&amp;")
              .replace(/</g, "&lt;")
              .replace(/>/g, "&gt;")}</pre>`;
          }
        }
        openPrintableResume(html, title);
      } catch (e) {
        console.warn("Resume PDF conversion failed:", e);
        toast.error(
          "Could not convert this document to a PDF preview. Try opening it directly in Word instead.",
        );
      }
    },
    [openPrintableResume],
  );

